"""Aggregate research/external/results/*.csv -> tables (stdout, also written to results_summary.txt) per PLAN.md section 5."""
import os, sys, glob, io
import numpy as np, pandas as pd
from scipy import stats
HERE = os.path.dirname(os.path.abspath(__file__))
OURS = ["SSC", "SSA", "SSR_k1.5", "BASILWs"]; REF = ["GAM-ridge"]
EXT = ["NOTEARS-MLP", "NOTEARS-MLP-gc", "DAGMA-nonlinear", "DCE-like", "GraN-DAG", "CAM-like", "NAM-SSC", "NAM-SSR_k1.5"]
ORDER = OURS + REF + EXT
CELLS = ["E1_d10_unif", "E3_d10_laplace", "E2_d20_unif"]
buf = io.StringIO()


def P(*a):
    print(*a); print(*a, file=buf)


def load():
    fr = [pd.read_csv(f) for f in sorted(glob.glob(os.path.join(HERE, "results", "E*.csv")))]
    return pd.concat(fr, ignore_index=True) if fr else pd.DataFrame()


def boot_ci(x, B=10000, seed=0):
    r = np.random.RandomState(seed); x = np.asarray(x, float); m = r.choice(x, (B, len(x))).mean(1); return np.percentile(m, [2.5, 97.5])


def fmt(x): return "%.3f" % x if np.isfinite(x) else "-"


def table(df, col, title, cells=CELLS, methods=ORDER, sd=True):
    P(f"\n### {title}")
    P("| method | " + " | ".join(cells) + " | pooled(30) |"); P("|---|" + "---|" * (len(cells) + 1))
    for m in methods:
        row = []
        for c in cells:
            v = df[(df.cell == c) & (df.method == m)][col].dropna()
            row.append(f"{fmt(v.mean())} ({fmt(v.std())}) n={len(v)}" if len(v) else "-")
        v = df[df.method == m][col].dropna()
        row.append(f"{fmt(v.mean())} ({fmt(v.std())}) n={len(v)}" if len(v) else "-")
        P(f"| {m} | " + " | ".join(row) + " |")


def paired(df, col, a, b, cells=CELLS, tag=""):
    """a minus b, paired by (cell, seed)"""
    out = []
    for c in cells + ["pooled"]:
        sub = df[df.cell.isin(cells if c == "pooled" else [c])]
        x = sub[sub.method == a].set_index(["cell", "seed"])[col]; y = sub[sub.method == b].set_index(["cell", "seed"])[col]
        j = pd.concat([x, y], axis=1, keys=["a", "b"]).dropna(); dlt = (j.a - j.b).values
        if len(dlt) < 3: out.append((c, len(dlt), np.nan, np.nan, np.nan, np.nan, 0)); continue
        try: p = stats.wilcoxon(dlt).pvalue if np.any(dlt != 0) else 1.0
        except Exception: p = np.nan
        lo, hi = boot_ci(dlt); out.append((c, len(dlt), dlt.mean(), lo, hi, p, int((dlt < 0).sum())))
    return out


def verdict(mean, lo, hi, band, lower_better=True):
    if not np.isfinite(mean): return "n/a"
    s = mean if lower_better else -mean
    if abs(s) <= band: return "tie"
    if s < -band and ((hi < 0) if lower_better else (lo > 0)): return "A better"
    if s > band and ((lo > 0) if lower_better else (hi < 0)): return "B better"
    return "inconclusive (|diff|>band, CI includes 0)"


def main():
    df = load()
    if df.empty: print("no results"); return
    err = df[df.error.fillna("") != ""]
    P("# Aggregated results (auto-generated by aggregate.py)\n")
    P("datasets per cell:", df.groupby("cell").seed.nunique().to_dict(), "| error rows:", len(err))
    if len(err): P(err[["cell", "seed", "method", "error"]].to_string())
    d = df[df.error.fillna("") == ""]
    table(d, "nrmse_topk", "Edge-function NRMSE, TOPK rule (PRIMARY; oracle count k=|E|; missed=1). mean (sd over datasets)")
    table(d, "nrmse_own", "Edge-function NRMSE, OWN graph rule (missed=1; n/a for methods without selection)")
    table(d, "nrmse_raw", "Edge-function NRMSE, RAW (no selection)")
    table(d, "r2_topk", "Curve R2, TOPK")
    table(d, "slope_topk", "Median calibration slope, TOPK (1 = right amplitude)")
    table(d, "slope_raw", "Median calibration slope, RAW")
    table(d, "auroc", "Directed AUROC of edge scores"); table(d, "skel_auroc", "Skeleton AUROC"); table(d, "orient", "Orientation accuracy on true edges")
    table(d, "do_direct", "Do-effect NRMSE, direct pairs"); table(d, "do_indirect", "Do-effect NRMSE, indirect pairs")
    table(d, "own_nedges", "Own graph: number of edges selected"); table(d, "own_tp", "Own graph: true positives (directed)"); table(d, "n_edges", "True edges", methods=["SSC"])
    table(d, "time", "Fit time, seconds (mean)")
    P("\n### Median fit time (s), pooled by d")
    for dd in (10, 20):
        P(f"d={dd}: " + ", ".join(f"{m}={d[(d.d == dd) & (d.method == m)].time.median():.1f}" for m in ORDER if len(d[(d.d == dd) & (d.method == m)].time.dropna())))
    # best arms
    piv = d.groupby("method").nrmse_topk.mean()
    ours_best = piv[[m for m in OURS if m in piv.index]].idxmin(); ext_best = piv[[m for m in EXT if m in piv.index]].idxmin()
    P(f"\nBest our arm (pooled TOPK NRMSE): {ours_best} = {piv[ours_best]:.3f}; best external arm: {ext_best} = {piv[ext_best]:.3f}")
    for col, band, lb, nm in (("nrmse_topk", 0.03, True, "TOPK NRMSE (primary)"), ("nrmse_own", 0.03, True, "OWN NRMSE"), ("nrmse_raw", 0.03, True, "RAW NRMSE"),
                              ("auroc", 0.03, False, "AUROC"), ("do_direct", 0.05, True, "do direct"), ("do_indirect", 0.05, True, "do indirect")):
        P(f"\n### Paired: our best ({ours_best}) minus external best ({ext_best}) on {nm}; Wilcoxon p, bootstrap 95% CI of mean diff (A=ours, B=external)")
        P("| cell | n | mean diff | CI | Wilcoxon p | #ours better | verdict |"); P("|---|---|---|---|---|---|---|")
        for c, n, mn, lo, hi, p, nb in paired(d, col, ours_best, ext_best):
            P(f"| {c} | {n} | {fmt(mn)} | [{fmt(lo)}, {fmt(hi)}] | {fmt(p)} | {nb} | {verdict(mn, lo, hi, band, lb)} |")
    P("\n### All external arms vs our best arm, TOPK NRMSE (external minus ours; negative = external better)")
    P("| external | " + " | ".join(CELLS) + " | pooled |"); P("|---|" + "---|" * (len(CELLS) + 1))
    for m in EXT + REF:
        r = paired(d, "nrmse_topk", m, ours_best); P(f"| {m} | " + " | ".join(f"{fmt(x[2])} [{fmt(x[3])},{fmt(x[4])}] p={fmt(x[5])}" for x in r) + " |")
    P("\n### All external arms vs our best arm, AUROC (external minus ours)")
    P("| external | " + " | ".join(CELLS) + " | pooled |"); P("|---|" + "---|" * (len(CELLS) + 1))
    for m in EXT + REF:
        r = paired(d, "auroc", m, ours_best); P(f"| {m} | " + " | ".join(f"{fmt(x[2])} [{fmt(x[3])},{fmt(x[4])}] p={fmt(x[5])}" for x in r) + " |")
    P("\n### Within-family: BASILWs - SSR_k1.5, SSA - SSR_k1.5, NAM-SSR_k1.5 - SSR_k1.5, NAM-SSC - SSC (TOPK NRMSE)")
    for a, b in (("BASILWs", "SSR_k1.5"), ("SSA", "SSR_k1.5"), ("NAM-SSR_k1.5", "SSR_k1.5"), ("NAM-SSC", "SSC")):
        r = paired(d, "nrmse_topk", a, b); P(f"{a} - {b}: " + " | ".join(f"{x[0]} {fmt(x[2])} [{fmt(x[3])},{fmt(x[4])}] p={fmt(x[5])}" for x in r))
    open(os.path.join(HERE, "results_summary.txt"), "w").write(buf.getvalue())


if __name__ == "__main__": main()
